using System.Net;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Logging;

namespace Alveara.Api.ChainHost;

/// <summary>
/// What a chain run's control routes need: the run's id, the per-run control token (generated by Invoke-AccumulatedChain.ps1 for this run only) and the evidence file each clock advance is appended to.
/// With no token the advance route is OFF and answers 404, so a chain host started without one (for example by the walkthrough runner) has no way to move its clock.
/// </summary>
public sealed record ChainControlOptions(string? RunId, string? ControlToken, string? ClockLogPath)
{
    public static readonly ChainControlOptions Disabled = new(null, null, null);
    public bool AdvanceEnabled => !string.IsNullOrWhiteSpace(ControlToken);
}

/// <summary>The record of one clock advance: returned to the caller and appended to the run's evidence (one JSON line per advance).</summary>
public sealed record ClockAdvanceRecord(string? RunId, DateTimeOffset PreviousUtc, int AdvancedByMinutes, DateTimeOffset UtcNow, DateTimeOffset RecordedAtRealUtc);

/// <summary>
/// ALV-N021 A2 (owner decision of 2026-11-15, case 3.09): <c>POST /api/chain/clock/advance</c> with body <c>{"minutes": n}</c> moves the chain run's injected clock forward, so a chain stage can let an
/// appointment's start pass (a no-show) without editing database rows. Narrow, test-only supporting infrastructure inside ALV-N021 A2; it does not reopen ALV-N019's clock seam.
///
/// - Only in the chain host, and only when the run gave it a control token (<see cref="ChainControlOptions.AdvanceEnabled"/>); otherwise 404. The production application never has this route.
/// - The caller must send the run's token in <c>X-Chain-Control-Token</c> (constant-time compare) from the local machine; otherwise 403 and nothing changes.
/// - Forward only: <c>minutes</c> must be a whole number from 1 to <see cref="MaxMinutes"/> (30 days); zero, negative, fractional, missing, malformed, oversized or extra-field bodies are 400 and nothing changes.
///   Time cannot go backwards (<see cref="ChainPracticeClock.Advance"/> refuses it too).
/// - It changes ONLY this host's injected <see cref="ChainPracticeClock"/>: never the system time, never a database row, never configuration. Sign-in expiry and retries keep real time (PD-32).
/// - Every advance is logged and appended to the run's evidence file as <see cref="ClockAdvanceRecord"/>: run id, old time, minutes, new time.
/// </summary>
public sealed class ClockAdvanceStartupFilter(ChainPracticeClock clock, ChainControlOptions options, ILogger<ClockAdvanceStartupFilter> logger) : IStartupFilter
{
    public const string Route = "/api/chain/clock/advance";
    public const string TokenHeader = "X-Chain-Control-Token";
    public const int MaxMinutes = 30 * 24 * 60;
    private static readonly object FileLock = new();

    public Action<IApplicationBuilder> Configure(Action<IApplicationBuilder> next) => app =>
    {
        app.Use(async (context, pipeline) =>
        {
            if (context.Request.Path != Route) { await pipeline(); return; }
            if (!options.AdvanceEnabled) { context.Response.StatusCode = StatusCodes.Status404NotFound; return; }
            if (!HttpMethods.IsPost(context.Request.Method)) { context.Response.StatusCode = StatusCodes.Status405MethodNotAllowed; return; }
            if (!IsLocal(context) || !TokenMatches(context.Request.Headers[TokenHeader].ToString()))
            {
                logger.LogWarning("chain_clock_advance_refused run={RunId} reason=not_authorized", options.RunId);
                await Refuse(context, 403, "not_authorized", "Only this chain run may move its clock.");
                return;
            }

            var minutes = await ReadMinutesAsync(context.Request);
            if (minutes is null)
            {
                await Refuse(context, 400, "invalid_advance", $"Send {{\"minutes\": n}} with a whole number of minutes from 1 to {MaxMinutes}. Time only moves forward.");
                return;
            }

            ClockAdvanceRecord record;
            lock (FileLock)   // one advance at a time, so the evidence lines and the clock agree
            {
                var before = clock.UtcNow;
                clock.Advance(TimeSpan.FromMinutes(minutes.Value));
                record = new ClockAdvanceRecord(options.RunId, before, minutes.Value, clock.UtcNow, DateTimeOffset.UtcNow);
                if (!string.IsNullOrWhiteSpace(options.ClockLogPath))
                    File.AppendAllText(options.ClockLogPath, JsonSerializer.Serialize(record, JsonSerializerOptions.Web) + Environment.NewLine, new UTF8Encoding(false));
            }
            logger.LogInformation("chain_clock_advanced run={RunId} from={Previous:O} minutes={Minutes} to={Now:O}", record.RunId, record.PreviousUtc, record.AdvancedByMinutes, record.UtcNow);
            context.Response.ContentType = "application/json";
            await context.Response.WriteAsJsonAsync(record);
        });
        next(app);
    };

    private bool TokenMatches(string presented)
    {
        var expected = Encoding.UTF8.GetBytes(options.ControlToken!);
        var given = Encoding.UTF8.GetBytes(presented);
        return given.Length == expected.Length && CryptographicOperations.FixedTimeEquals(given, expected);
    }

    /// <summary>The chain host listens on localhost; a request from another machine is refused. (An in-memory test server has no remote address, which is local by construction.)</summary>
    private static bool IsLocal(HttpContext context) => context.Connection.RemoteIpAddress is not { } ip || IPAddress.IsLoopback(ip);

    /// <summary>The whole number of minutes in a body of exactly <c>{"minutes": n}</c>, 1 to <see cref="MaxMinutes"/>; null for anything else.</summary>
    private static async Task<int?> ReadMinutesAsync(HttpRequest request)
    {
        try
        {
            using var body = await JsonDocument.ParseAsync(request.Body);
            var root = body.RootElement;
            if (root.ValueKind != JsonValueKind.Object || root.EnumerateObject().Count() != 1 || !root.TryGetProperty("minutes", out var value)) return null;
            if (value.ValueKind != JsonValueKind.Number || !value.TryGetInt32(out var minutes)) return null;
            return minutes is >= 1 and <= MaxMinutes ? minutes : null;
        }
        catch (JsonException)
        {
            return null;   // malformed JSON: refused below with 400, nothing changes
        }
    }

    private static async Task Refuse(HttpContext context, int status, string code, string message)
    {
        context.Response.StatusCode = status;
        context.Response.ContentType = "application/json";
        await context.Response.WriteAsJsonAsync(new { error = code, message });
    }
}
